export const TILE_MAP = TILES.reduce((acc, tile) => {
  acc[tile.id] = tile;
  return acc;
}, {} as Record<string, TileDefinition>);

export const DEFAULT_TILE = 'ground';

import React from 'react';
import { TileDefinition } from '../types';

interface TileIconProps {
  tile: TileDefinition;
  className?: string;
}

export const TileIcon: React.FC<TileIconProps> = ({ tile, className }) => {
  const { bgColor, fgColor, iconType } = tile;

  const renderContent = () => {
    switch (iconType) {
      case 'solid':
        return null;
      case 'waves':
        return (
          <svg viewBox="0 0 100 100" fill="none" stroke={fgColor} strokeWidth="8">
             <path d="M0 30 Q 25 10 50 30 T 100 30" />
             <path d="M0 50 Q 25 30 50 50 T 100 50" />
             <path d="M0 70 Q 25 50 50 70 T 100 70" />
          </svg>
        );
      case 'grid':
        return (
          <svg viewBox="0 0 100 100" fill="none" stroke={fgColor} strokeWidth="4">
            <path d="M25 0 V100 M50 0 V100 M75 0 V100" />
            <path d="M0 25 H100 M0 50 H100 M0 75 H100" />
          </svg>
        );
      case 'road_i':
      case 'channel_i':
      case 'ind_road_i':
      case 'dock_i':
        return (
          <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
             {iconType === 'road_i' && <path d="M50 0 V100" stroke={bgColor} strokeWidth="2" strokeDasharray="10 5" />}
          </svg>
        );
      case 'road_l':
      case 'channel_l':
      case 'channel_long_l': // Simplified as L for now
        return (
          <svg viewBox="0 0 100 100">
             <path d="M35 0 V50 A15 15 0 0 0 50 65 H100 V35 H50 A15 15 0 0 1 65 20 V0 Z" fill={fgColor} stroke="none" />
             {iconType === 'road_l' && <path d="M50 0 V50 H100" fill="none" stroke={bgColor} strokeWidth="2" strokeDasharray="10 5" />}
          </svg>
        );
      case 'road_t':
      case 'channel_t':
      case 'ind_road_t':
        return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
             <rect x="35" y="35" width="65" height="30" fill={fgColor} />
           </svg>
        );
      case 'road_x':
      case 'channel_x':
      case 'ind_road_x':
        return (
          <svg viewBox="0 0 100 100">
            <rect x="35" y="0" width="30" height="100" fill={fgColor} />
            <rect x="0" y="35" width="100" height="30" fill={fgColor} />
          </svg>
        );
       case 'road_end':
       case 'channel_end':
       case 'ind_road_end':
        return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="50" width="30" height="50" fill={fgColor} />
             <circle cx="50" cy="50" r="15" fill={fgColor} />
           </svg>
        );
      case 'ind_road_c':
         return (
          <svg viewBox="0 0 100 100">
             <path d="M35 0 V50 A15 15 0 0 0 50 65 H100 V35 H50 A15 15 0 0 1 65 20 V0 Z" fill={fgColor} stroke="none" />
          </svg>
         );
      case 'bridge':
        return (
          <svg viewBox="0 0 100 100">
             <rect x="25" y="0" width="50" height="100" fill={fgColor} />
             <line x1="25" y1="20" x2="75" y2="20" stroke="black" strokeWidth="2" />
             <line x1="25" y1="50" x2="75" y2="50" stroke="black" strokeWidth="2" />
             <line x1="25" y1="80" x2="75" y2="80" stroke="black" strokeWidth="2" />
          </svg>
        );
      case 'uphill':
        return (
           <svg viewBox="0 0 100 100">
              <path d="M20 90 L80 10" stroke={fgColor} strokeWidth="15" />
              <path d="M35 90 L95 10" stroke="rgba(0,0,0,0.2)" strokeWidth="15" />
           </svg>
        );
      case 'dock_l_ext':
        return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            <path d="M0 0 H70 V70 H0 Z" fill={fgColor} />
          </svg>
        );
      case 'dock_l_int':
         return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            <path d="M30 30 H100 V100 H30 Z" fill={fgColor} />
          </svg>
        );
      case 'dock_u':
         return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            <path d="M20 0 V80 H80 V0" fill="none" stroke={fgColor} strokeWidth="20" />
          </svg>
         );
       case 'dock_2_channel':
         return (
           <svg viewBox="0 0 100 100" fill={bgColor}>
             <rect width="100" height="100" />
             <rect x="30" y="0" width="40" height="100" fill={fgColor} />
             <rect x="0" y="30" width="100" height="40" fill={fgColor} />
           </svg>
         );
      case 'factory':
        return (
          <svg viewBox="0 0 100 100" fill={fgColor}>
            <path d="M10 90 V50 L30 70 L30 30 L50 50 L50 10 L90 90 Z" />
            <rect x="20" y="70" width="10" height="20" fill={bgColor} />
            <rect x="60" y="70" width="20" height="20" fill={bgColor} />
          </svg>
        );
       case 'channel_foot':
         return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
             <rect x="0" y="40" width="100" height="20" fill="#92400e" />
             <line x1="0" y1="42" x2="100" y2="42" stroke="rgba(0,0,0,0.3)" strokeWidth="2" />
             <line x1="0" y1="58" x2="100" y2="58" stroke="rgba(0,0,0,0.3)" strokeWidth="2" />
           </svg>
         );
      default:
        return null;
    }
  };

  return (
    <div 
      className={`relative w-full h-full overflow-hidden ${className}`} 
      style={{ backgroundColor: bgColor }}
    >
      {renderContent()}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { TILES } from '../constants';
import { TileCategory } from '../types';
import { TileIcon } from './TileIcon';

interface TilePaletteProps {
  selectedTileId: string;
  onSelectTile: (id: string) => void;
}

export const TilePalette: React.FC<TilePaletteProps> = ({ selectedTileId, onSelectTile }) => {
  const [activeCategory, setActiveCategory] = useState<TileCategory>(TileCategory.TERRAIN);

  // Group tiles by category for rendering
  const categories = useMemo(() => {
    return Object.values(TileCategory);
  }, []);

  const filteredTiles = useMemo(() => {
    return TILES.filter(t => t.category === activeCategory);
  }, [activeCategory]);

  return (
    <div className="flex flex-col h-full bg-slate-900 border-r border-slate-800">
      <div className="p-4 border-b border-slate-800">
        <h2 className="text-xl font-bold text-slate-100">Tools</h2>
        <p className="text-xs text-slate-400 mt-1">Select a tile type to paint</p>
      </div>

      {/* Category Tabs */}
      <div className="flex overflow-x-auto p-2 gap-1 border-b border-slate-800 scrollbar-hide">
        {categories.map((cat) => (
          <button
            key={cat}
            onClick={() => setActiveCategory(cat)}
            className={`px-3 py-1.5 text-xs font-medium rounded-full whitespace-nowrap transition-colors ${
              activeCategory === cat
                ? 'bg-brand-600 text-white shadow-lg shadow-brand-600/20'
                : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-slate-200'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Tile Grid */}
      <div className="flex-1 overflow-y-auto p-4">
        <div className="grid grid-cols-2 gap-3">
          {filteredTiles.map((tile) => (
            <button
              key={tile.id}
              onClick={() => onSelectTile(tile.id)}
              className={`group flex flex-col items-center gap-2 p-2 rounded-xl border-2 transition-all ${
                selectedTileId === tile.id
                  ? 'border-brand-500 bg-slate-800 shadow-lg shadow-brand-500/20'
                  : 'border-transparent bg-slate-800/50 hover:bg-slate-800 hover:border-slate-700'
              }`}
            >
              <div className="w-12 h-12 rounded-lg overflow-hidden ring-1 ring-slate-900/10 shadow-sm">
                <TileIcon tile={tile} />
              </div>
              <span className={`text-xs text-center font-medium ${
                selectedTileId === tile.id ? 'text-brand-400' : 'text-slate-400 group-hover:text-slate-200'
              }`}>
                {tile.label}
              </span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

import React, { useCallback } from 'react';
import { GRID_COLS, GRID_ROWS, TILE_MAP } from '../constants';
import { GridState } from '../types';
import { TileIcon } from './TileIcon';

interface MapGridProps {
  grid: GridState;
  onCellClick: (row: number, col: number) => void;
  onCellEnter: (row: number, col: number) => void;
}

export const MapGrid: React.FC<MapGridProps> = ({ grid, onCellClick, onCellEnter }) => {
  const handleMouseDown = useCallback((r: number, c: number) => {
    onCellClick(r, c);
  }, [onCellClick]);

  const handleMouseEnter = useCallback((r: number, c: number) => {
    onCellEnter(r, c);
  }, [onCellEnter]);

  return (
    <div className="w-full h-full p-8 flex items-center justify-center bg-slate-950 overflow-auto">
      <div 
        className="grid bg-slate-900 border-4 border-slate-800 shadow-2xl shadow-black rounded-lg overflow-hidden"
        style={{
          gridTemplateColumns: `repeat(${GRID_COLS}, minmax(32px, 1fr))`,
          gridTemplateRows: `repeat(${GRID_ROWS}, minmax(32px, 1fr))`,
          aspectRatio: `${GRID_COLS}/${GRID_ROWS}`,
          width: '100%',
          maxWidth: '1200px', // Prevent it from getting too huge on large screens
        }}
        onMouseLeave={() => {
            // Optional: stop drawing state if needed
        }}
      >
        {grid.map((row, rIndex) =>
          row.map((tileId, cIndex) => {
            const tile = TILE_MAP[tileId];
            return (
              <div
                key={`${rIndex}-${cIndex}`}
                onMouseDown={(e) => {
                    e.preventDefault(); // prevent drag behavior
                    handleMouseDown(rIndex, cIndex);
                }}
                onMouseEnter={(e) => {
                    if (e.buttons === 1) {
                         handleMouseEnter(rIndex, cIndex);
                    }
                }}
                className="relative border border-slate-800/30 cursor-crosshair hover:ring-2 hover:ring-white/50 hover:z-10 transition-none"
                title={`Row: ${rIndex + 1}, Col: ${cIndex + 1}`}
              >
                {tile && <TileIcon tile={tile} className="w-full h-full" />}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { GridState } from '../types';
import { TILES, TILE_MAP } from '../constants';

interface ReportPanelProps {
  grid: GridState;
  onReset: () => void;
  onExport: () => void;
}

export const ReportPanel: React.FC<ReportPanelProps> = ({ grid, onReset, onExport }) => {
  // Calculate counts
  const counts = useMemo(() => {
    const map = new Map<string, number>();
    // Initialize all to 0 so they show up? Or only show used?
    // User probably wants to see list of things needed. 
    // Let's only show what is used > 0 to keep it clean, or maybe show all?
    // A bill of materials usually shows what you need.

    grid.flat().forEach(tileId => {
      map.set(tileId, (map.get(tileId) || 0) + 1);
    });
    return map;
  }, [grid]);

  const usedTiles = useMemo(() => {
    return TILES.filter(t => (counts.get(t.id) || 0) > 0).sort((a, b) => {
        // Sort by Category then Name
        if (a.category !== b.category) return a.category.localeCompare(b.category);
        return a.label.localeCompare(b.label);
    });
  }, [counts]);

  const totalTiles = grid.flat().length;

  return (
    <div className="flex flex-col h-full bg-slate-900 border-l border-slate-800">
      <div className="p-6 border-b border-slate-800 bg-slate-900">
        <div className="flex items-center justify-between mb-2">
            <h2 className="text-xl font-bold text-white">Bill of Materials</h2>
            <span className="text-xs font-mono text-slate-500 bg-slate-800 px-2 py-1 rounded">
                Total: {totalTiles}
            </span>
        </div>
        <p className="text-sm text-slate-400">
            Quantity of each tile type required for the current layout.
        </p>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        {usedTiles.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-slate-500 opacity-50">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p>Map is empty</p>
          </div>
        ) : (
          <div className="space-y-6">
             {/* Group by category visually in the list */}
             {Array.from(new Set(usedTiles.map(t => t.category))).map(cat => (
                 <div key={cat}>
                    <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3 ml-1">{cat}</h3>
                    <div className="space-y-2">
                        {usedTiles.filter(t => t.category === cat).map(tile => (
                            <div key={tile.id} className="flex items-center justify-between p-3 bg-slate-800 rounded-lg border border-slate-700/50">
                                <div className="flex items-center gap-3">
                                    <div 
                                        className="w-8 h-8 rounded border border-white/10 shadow-sm"
                                        style={{ backgroundColor: tile.bgColor }}
                                    ></div>
                                    <span className="text-sm font-medium text-slate-200">{tile.label}</span>
                                </div>
                                <span className="text-lg font-bold text-brand-400 font-mono">
                                    {counts.get(tile.id)}
                                </span>
                            </div>
                        ))}
                    </div>
                 </div>
             ))}
          </div>
        )}
      </div>

      <div className="p-6 border-t border-slate-800 bg-slate-900/50">
        <div className="grid grid-cols-2 gap-4">
            <button 
                onClick={onReset}
                className="flex items-center justify-center gap-2 px-4 py-3 bg-rose-900/30 hover:bg-rose-900/50 text-rose-400 rounded-lg transition-colors border border-rose-900/50 text-sm font-medium"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                Clear Map
            </button>
            <button 
                onClick={onExport}
                className="flex items-center justify-center gap-2 px-4 py-3 bg-brand-600 hover:bg-brand-500 text-white rounded-lg transition-colors shadow-lg shadow-brand-600/20 text-sm font-medium"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                Export JSON
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MapGrid } from './components/MapGrid';
import { TilePalette } from './components/TilePalette';
import { ReportPanel } from './components/ReportPanel';
import { GridState } from './types';
import { DEFAULT_TILE, GRID_COLS, GRID_ROWS } from './constants';

const INITIAL_GRID: GridState = Array(GRID_ROWS).fill(null).map(() => Array(GRID_COLS).fill(DEFAULT_TILE));

export default function App() {
  const [grid, setGrid] = useState<GridState>(INITIAL_GRID);
  const [selectedTileId, setSelectedTileId] = useState<string>(DEFAULT_TILE);

  const handleCellClick = (row: number, col: number) => {
    setGrid(prevGrid => {
      const newGrid = prevGrid.map(r => [...r]);
      newGrid[row][col] = selectedTileId;
      return newGrid;
    });
  };

  const handleCellEnter = (row: number, col: number) => {
    // This supports drag-to-paint
    setGrid(prevGrid => {
      // Optimization: only update if different to avoid rerenders
      if (prevGrid[row][col] === selectedTileId) return prevGrid;

      const newGrid = prevGrid.map(r => [...r]);
      newGrid[row][col] = selectedTileId;
      return newGrid;
    });
  };

  const handleReset = () => {
    if (confirm('Are you sure you want to clear the entire map?')) {
        setGrid(Array(GRID_ROWS).fill(null).map(() => Array(GRID_COLS).fill(DEFAULT_TILE)));
    }
  };

  const handleExport = () => {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(grid));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "tilemap.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  return (
    <div className="flex flex-row h-screen w-full bg-slate-950 text-slate-200">

        {/* Left Side: Palette (Toolbox) - Fixed width */}
        <div className="w-64 h-full flex-shrink-0 z-20 shadow-xl">
