import React, { useCallback } from 'react';
import { TILE_MAP } from '../constants';
import { GridState } from '../types';
import { TileIcon } from './TileIcon';

interface MapGridProps {
  grid: GridState;
  onCellClick: (row: number, col: number) => void;
  onCellEnter: (row: number, col: number) => void;
}

export const MapGrid: React.FC<MapGridProps> = ({ grid, onCellClick, onCellEnter }) => {
  const handleMouseDown = useCallback((r: number, c: number) => {
    onCellClick(r, c);
  }, [onCellClick]);

  const handleMouseEnter = useCallback((r: number, c: number) => {
    onCellEnter(r, c);
  }, [onCellEnter]);

  // Derive dimensions from current grid state
  const rows = grid.length;
  const cols = grid[0]?.length || 0;

  return (
    <div className="w-full h-full p-8 flex items-center justify-center bg-slate-950 overflow-auto">
      <div 
        className="grid bg-slate-900 border-4 border-slate-800 shadow-2xl shadow-black rounded-lg overflow-hidden transition-all duration-300 ease-in-out"
        style={{
          gridTemplateColumns: `repeat(${cols}, minmax(32px, 1fr))`,
          gridTemplateRows: `repeat(${rows}, minmax(32px, 1fr))`,
          aspectRatio: `${cols}/${rows}`,
          width: '100%',
          maxWidth: '1200px', // Prevent it from getting too huge on large screens
        }}
        onMouseLeave={() => {
            // Optional: stop drawing state if needed
        }}
      >
        {grid.map((row, rIndex) =>
          row.map((cell, cIndex) => {
            const tile = TILE_MAP[cell.tileId];
            return (
              <div
                key={`${rIndex}-${cIndex}`}
                onMouseDown={(e) => {
                    e.preventDefault(); // prevent drag behavior
                    handleMouseDown(rIndex, cIndex);
                }}
                onMouseEnter={(e) => {
                    if (e.buttons === 1) {
                         handleMouseEnter(rIndex, cIndex);
                    }
                }}
                className="relative border border-slate-800/30 cursor-crosshair hover:ring-2 hover:ring-white/50 hover:z-10 transition-transform duration-200"
                title={`Row: ${rIndex + 1}, Col: ${cIndex + 1}, Rot: ${cell.rotation}°`}
              >
                <div className="w-full h-full" style={{ transform: `rotate(${cell.rotation}deg)` }}>
                    {tile && <TileIcon tile={tile} className="w-full h-full" />}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';

interface ResizeModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (rows: number, cols: number) => void;
  currentRows: number;
  currentCols: number;
}

export const ResizeModal: React.FC<ResizeModalProps> = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  currentRows, 
  currentCols 
}) => {
  const [rows, setRows] = useState(currentRows);
  const [cols, setCols] = useState(currentCols);

  useEffect(() => {
    if (isOpen) {
      setRows(currentRows);
      setCols(currentCols);
    }
  }, [isOpen, currentRows, currentCols]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="w-full max-w-md bg-slate-900 border border-slate-700 rounded-xl shadow-2xl transform transition-all">
        <div className="p-6 border-b border-slate-800">
          <h2 className="text-xl font-bold text-white">Resize Grid</h2>
          <p className="text-sm text-slate-400 mt-1">
            Changing the size will preserve existing tiles from the top-left corner.
          </p>
        </div>

        <div className="p-6 grid grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300">Width (Columns)</label>
            <input 
              type="number" 
              min="1" 
              max="50"
              value={cols}
              onChange={(e) => setCols(Math.max(1, Math.min(50, parseInt(e.target.value) || 1)))}
              className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500/50"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-300">Height (Rows)</label>
            <input 
              type="number" 
              min="1" 
              max="50"
              value={rows}
              onChange={(e) => setRows(Math.max(1, Math.min(50, parseInt(e.target.value) || 1)))}
              className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-white focus:border-brand-500 focus:outline-none focus:ring-1 focus:ring-brand-500/50"
            />
          </div>
        </div>

        <div className="p-6 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-3 rounded-b-xl">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-400 hover:text-white transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={() => onConfirm(rows, cols)}
