                 <div className="flex items-baseline gap-2">
                    <span className="text-2xl font-bold text-white">{totalWidth}" x {totalHeight}"</span>
                    <span className="text-sm text-slate-400">({totalWidthFt}' x {totalHeightFt}')</span>
                 </div>
                 <div className="text-sm text-slate-500 font-mono">
                    {totalWidthCm} cm x {totalHeightCm} cm
                 </div>
             </div>
          </div>
        </div>

        <div className="p-6 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-3 rounded-b-xl">
          <button 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-400 hover:text-white transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={() => onConfirm(rows, cols, tileSize)}
            className="px-4 py-2 bg-brand-600 hover:bg-brand-500 text-white text-sm font-medium rounded-lg shadow-lg shadow-brand-600/20 transition-all hover:scale-105 active:scale-95"
          >
            Apply Changes
          </button>
        </div>
      </div>
    </div>
  );
};

import { useState, useEffect } from 'react';
import { MapGrid } from './components/MapGrid';
import { TilePalette } from './components/TilePalette';
import { ReportPanel } from './components/ReportPanel';
import { ResizeModal } from './components/ResizeModal';
import { HelpModal } from './components/HelpModal';
import { GridState, CellData } from './types';
import { DEFAULT_TILE, DEFAULT_COLS, DEFAULT_ROWS } from './constants';

const createInitialGrid = (rows: number, cols: number): GridState => 
  Array.from({ length: rows }, () => 
    Array.from({ length: cols }, () => ({ tileId: DEFAULT_TILE, rotation: 0 }))
  );

export default function App() {
  const [grid, setGrid] = useState<GridState>(() => createInitialGrid(DEFAULT_ROWS, DEFAULT_COLS));
  const [selectedTileId, setSelectedTileId] = useState<string>(DEFAULT_TILE);
  const [inventory, setInventory] = useState<Record<string, number>>({});
  const [tileSize, setTileSize] = useState<number>(4); // Default 4 inches
  const [isResizeModalOpen, setIsResizeModalOpen] = useState(false);
  const [isHelpModalOpen, setIsHelpModalOpen] = useState(false);

  // Load inventory from local storage on mount
  useEffect(() => {
    const savedInventory = localStorage.getItem('tilemap_inventory');
    if (savedInventory) {
      try {
        setInventory(JSON.parse(savedInventory));
      } catch (e) {
        console.error("Failed to load inventory from local storage", e);
      }
    }
  }, []);

  const handleUpdateInventory = (id: string, count: number) => {
    setInventory(prev => {
      const next = { ...prev, [id]: count };
      localStorage.setItem('tilemap_inventory', JSON.stringify(next));
      return next;
    });
  };

  const handleCellClick = (row: number, col: number) => {
    setGrid(prevGrid => {
      const newGrid = prevGrid.map(r => r.map(c => ({ ...c })));
      const cell = newGrid[row][col];

      if (cell.tileId === selectedTileId) {
        // Rotate if same tile
        cell.rotation = (cell.rotation + 90) % 360;
      } else {
        // Place new tile
        cell.tileId = selectedTileId;
        cell.rotation = 0;
      }
      return newGrid;
    });
  };

  const handleCellEnter = (row: number, col: number) => {
    // This supports drag-to-paint
    setGrid(prevGrid => {
      // Optimization: only update if different to avoid rerenders
      if (prevGrid[row][col].tileId === selectedTileId) return prevGrid;

      const newGrid = prevGrid.map(r => r.map(c => ({ ...c })));
      newGrid[row][col] = { tileId: selectedTileId, rotation: 0 };
      return newGrid;
    });
  };

  const handleReset = () => {
      // Explicitly set all tiles to 'ground' based on current grid size
      setGrid(prevGrid => 
          Array.from({ length: prevGrid.length }, () => 
              Array.from({ length: prevGrid[0].length }, () => ({ tileId: 'ground', rotation: 0 }))
          )
      );
  };

  const handleResize = (newRows: number, newCols: number, newTileSize: number) => {
    setTileSize(newTileSize);
    setGrid(prevGrid => {
      const newGrid: GridState = [];
      for (let r = 0; r < newRows; r++) {
        const newRow: CellData[] = [];
        for (let c = 0; c < newCols; c++) {
          if (r < prevGrid.length && c < prevGrid[0].length) {
            // Preserve existing cell
            newRow.push({ ...prevGrid[r][c] });
          } else {
            // New cell
            newRow.push({ tileId: DEFAULT_TILE, rotation: 0 });
          }
        }
        newGrid.push(newRow);
      }
      return newGrid;
    });
    setIsResizeModalOpen(false);
  };

  const handleExportGrid = () => {
      const exportData = {
          rows: grid.length,
          cols: grid[0]?.length || 0,
          tileSize: tileSize,
          grid: grid
      };
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "tilemap_grid.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleImportGrid = () => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'application/json';
      input.onchange = (e) => {
          const file = (e.target as HTMLInputElement).files?.[0];
          if (!file) return;

          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const content = event.target?.result as string;
                  const data = JSON.parse(content);

                  // Support both wrapped format and legacy raw array
                  if (data.grid && Array.isArray(data.grid)) {
                      setGrid(data.grid);
                      if (data.tileSize && typeof data.tileSize === 'number') {
                          setTileSize(data.tileSize);
                      }
                  } else if (Array.isArray(data)) {
                      setGrid(data);
                  } else {
                      alert('Invalid grid file format');
                  }
              } catch (error) {
                  console.error('Error importing grid:', error);
                  alert('Failed to import grid file. Check console for details.');
              }
          };
          reader.readAsText(file);
      };
      input.click();
  };

  const handleExportCollection = () => {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(inventory, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", "tilemap_inventory.json");
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleImportCollection = () => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'application/json';
      input.onchange = (e) => {
          const file = (e.target as HTMLInputElement).files?.[0];
          if (!file) return;

          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const content = event.target?.result as string;
                  const data = JSON.parse(content);
                  if (typeof data === 'object' && data !== null) {
                      setInventory(data);
                      localStorage.setItem('tilemap_inventory', JSON.stringify(data));
                  } else {
                      alert('Invalid collection file format');
                  }
              } catch (error) {
                  console.error('Error importing collection:', error);
                  alert('Failed to import collection file. Check console for details.');
              }
          };
          reader.readAsText(file);
      };
      input.click();
  };

  const totalWidthInches = (grid[0]?.length || 0) * tileSize;
  const totalHeightInches = grid.length * tileSize;
  const totalWidthCm = Math.round(totalWidthInches * 2.54);
  const totalHeightCm = Math.round(totalHeightInches * 2.54);

  return (
    <div className="flex flex-row h-screen w-full bg-slate-950 text-slate-200">

        <ResizeModal 
          isOpen={isResizeModalOpen}
          onClose={() => setIsResizeModalOpen(false)}
          onConfirm={handleResize}
          currentRows={grid.length}
          currentCols={grid[0]?.length || 0}
          currentTileSize={tileSize}
        />

        <HelpModal 
          isOpen={isHelpModalOpen}
          onClose={() => setIsHelpModalOpen(false)}
        />

        {/* Left Side: Palette (Toolbox) - Fixed width */}
        <div className="w-64 h-full flex-shrink-0 z-20 shadow-xl">
            <TilePalette 
                selectedTileId={selectedTileId} 
                onSelectTile={setSelectedTileId} 
            />
        </div>

        {/* Center: Map Area - Flexible grow */}
        <div className="flex-1 h-full relative flex flex-col min-w-0">
            {/* Header / Top Bar */}
            <div className="h-16 border-b border-slate-800 bg-slate-900/50 flex items-center justify-between px-6 backdrop-blur-sm z-10">
                <h1 className="text-xl font-bold text-white flex items-center gap-2">
                    <span className="w-3 h-3 rounded-full bg-brand-500 animate-pulse"></span>
                    TileMap Architect
                </h1>

                <div className="flex items-center gap-4">
                    <div className="text-sm text-slate-400 hidden lg:block">
                        {grid[0]?.length}x{grid.length} Grid <span className="text-slate-600 mx-1">|</span> {totalWidthInches}" x {totalHeightInches}" <span className="text-slate-600 mx-1">/</span> {totalWidthCm}cm x {totalHeightCm}cm
                    </div>
                    <div className="h-6 w-px bg-slate-800 mx-2 hidden lg:block"></div>

                    <button 
                        onClick={() => setIsResizeModalOpen(true)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-lg transition-colors border border-slate-700 text-xs font-medium"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                           <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 4l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                        </svg>
                        Resize Map
                    </button>

                    <button 
                        onClick={handleReset}
                        className="flex items-center gap-2 px-3 py-1.5 bg-rose-950/30 hover:bg-rose-900/40 text-rose-400 rounded-lg transition-colors border border-rose-900/30 text-xs font-medium"
                        title="Set all tiles to Ground"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                        Clear Map
                    </button>

                    <button 
                        onClick={() => setIsHelpModalOpen(true)}
                        className="flex items-center gap-2 px-3 py-1.5 bg-indigo-950/30 hover:bg-indigo-900/40 text-indigo-400 rounded-lg transition-colors border border-indigo-900/30 text-xs font-medium"
                        title="How to use"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        Help
                    </button>
                </div>
            </div>

            {/* Canvas */}
            <div className="flex-1 bg-slate-950 relative overflow-hidden">
                 {/* Subtle grid background pattern */}
                <div className="absolute inset-0 opacity-10 pointer-events-none" 
                    style={{ 
                        backgroundImage: 'radial-gradient(#475569 1px, transparent 1px)', 
                        backgroundSize: '20px 20px' 
                    }}>
                </div>

                <MapGrid 
                    grid={grid} 
                    onCellClick={handleCellClick} 
                    onCellEnter={handleCellEnter}
                />
            </div>
        </div>

        {/* Right Side: Report - 1/3 width essentially, but responsive */}
        <div className="w-80 lg:w-96 h-full flex-shrink-0 z-20 shadow-xl">
            <ReportPanel 
                grid={grid} 
                inventory={inventory}
                onUpdateInventory={handleUpdateInventory}
                onExportGrid={handleExportGrid}
                onImportGrid={handleImportGrid}
                onExportCollection={handleExportCollection}
                onImportCollection={handleImportCollection}
            />
        </div>

    </div>
  );
}

import React from 'react';
import { TileDefinition } from '../types';

interface TileIconProps {
  tile: TileDefinition;
  className?: string;
}

export const TileIcon: React.FC<TileIconProps> = ({ tile, className }) => {
  const { bgColor, fgColor, iconType } = tile;

  const renderContent = () => {
    switch (iconType) {
      case 'solid':
        return null;
      case 'waves':
        return (
          <svg viewBox="0 0 100 100" fill="none" stroke={fgColor} strokeWidth="8">
             <path d="M0 30 Q 25 10 50 30 T 100 30" />
             <path d="M0 50 Q 25 30 50 50 T 100 50" />
             <path d="M0 70 Q 25 50 50 70 T 100 70" />
          </svg>
        );
      case 'grid':
        return (
          <svg viewBox="0 0 100 100" fill="none" stroke={fgColor} strokeWidth="4">
            <path d="M25 0 V100 M50 0 V100 M75 0 V100" />
            <path d="M0 25 H100 M0 50 H100 M0 75 H100" />
          </svg>
        );
      case 'road_i':
      case 'channel_i':
      case 'ind_road_i':
        return (
          <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
             {iconType === 'road_i' && <path d="M50 0 V100" stroke={bgColor} strokeWidth="2" strokeDasharray="10 5" />}
          </svg>
        );
      case 'dock_i':
        return (
          <svg viewBox="0 0 100 100">
             {/* 1/3 Brown (bgColor is background), 2/3 Blue (fgColor) */}
             <rect x="33" y="0" width="67" height="100" fill={fgColor} />
          </svg>
        );
      case 'road_l':
      case 'channel_l':
      case 'channel_long_l': // Simplified as L for now
        return (
          <svg viewBox="0 0 100 100">
             <path d="M35 0 V50 A15 15 0 0 0 50 65 H100 V35 H50 A15 15 0 0 1 65 20 V0 Z" fill={fgColor} stroke="none" />
             {iconType === 'road_l' && <path d="M50 0 V50 H100" fill="none" stroke={bgColor} strokeWidth="2" strokeDasharray="10 5" />}
          </svg>
        );
      case 'road_t':
      case 'channel_t':
      case 'ind_road_t':
        return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
             <rect x="35" y="35" width="65" height="30" fill={fgColor} />
           </svg>
        );
      case 'road_x':
      case 'channel_x':
      case 'ind_road_x':
        return (
          <svg viewBox="0 0 100 100">
            <rect x="35" y="0" width="30" height="100" fill={fgColor} />
            <rect x="0" y="35" width="100" height="30" fill={fgColor} />
          </svg>
        );
       case 'road_end':
       case 'channel_end':
       case 'ind_road_end':
        return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="50" width="30" height="50" fill={fgColor} />
             <circle cx="50" cy="50" r="15" fill={fgColor} />
           </svg>
        );
      case 'ind_road_c':
         return (
          <svg viewBox="0 0 100 100">
             <path d="M35 0 V50 A15 15 0 0 0 50 65 H100 V35 H50 A15 15 0 0 1 65 20 V0 Z" fill={fgColor} stroke="none" />
          </svg>
         );
      case 'bridge':
        return (
          <svg viewBox="0 0 100 100">
             <rect x="25" y="0" width="50" height="100" fill={fgColor} />
             <line x1="25" y1="20" x2="75" y2="20" stroke="black" strokeWidth="2" />
             <line x1="25" y1="50" x2="75" y2="50" stroke="black" strokeWidth="2" />
             <line x1="25" y1="80" x2="75" y2="80" stroke="black" strokeWidth="2" />
          </svg>
        );
      case 'uphill':
        return (
           <svg viewBox="0 0 100 100">
             {/* Uses bridge style but will be red via fgColor */}
             <rect x="25" y="0" width="50" height="100" fill={fgColor} />
             <line x1="25" y1="20" x2="75" y2="20" stroke="black" strokeWidth="2" />
             <line x1="25" y1="50" x2="75" y2="50" stroke="black" strokeWidth="2" />
             <line x1="25" y1="80" x2="75" y2="80" stroke="black" strokeWidth="2" />
           </svg>
        );
      case 'dock_l_ext':
        return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            <path d="M0 0 H70 V70 H0 Z" fill={fgColor} />
          </svg>
        );
      case 'dock_l_int':
         return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            <path d="M30 30 H100 V100 H30 Z" fill={fgColor} />
          </svg>
        );
      case 'dock_u':
         return (
          <svg viewBox="0 0 100 100" fill={bgColor}>
            <rect width="100" height="100" />
            {/* Filled U shape: Water inlet */}
            <path d="M20 0 V80 H80 V0" fill={fgColor} stroke={fgColor} strokeWidth="20" />
          </svg>
         );
       case 'dock_2_channel':
         return (
           <svg viewBox="0 0 100 100" fill={bgColor}>
             <rect width="100" height="100" />
             <rect x="30" y="0" width="40" height="100" fill={fgColor} />
             <rect x="0" y="30" width="100" height="40" fill={fgColor} />
           </svg>
         );
      case 'factory':
        return (
          <svg viewBox="0 0 100 100" fill={fgColor}>
            <path d="M10 90 V50 L30 70 L30 30 L50 50 L50 10 L90 90 Z" />
            <rect x="20" y="70" width="10" height="20" fill={bgColor} />
            <rect x="60" y="70" width="20" height="20" fill={bgColor} />
          </svg>
        );
       case 'channel_foot':
         return (
           <svg viewBox="0 0 100 100">
             <rect x="35" y="0" width="30" height="100" fill={fgColor} />
              <rect x="0" y="35" width="100" height="30" fill="#ffffff" />
           </svg>
         );
      default:
        return null;
    }
  };

  return (
    <div 
      className={`relative w-full h-full overflow-hidden ${className}`} 
      style={{ backgroundColor: bgColor }}
    >
      {renderContent()}
    </div>
  );
};

